#include <HBEngine/SceneRender.hpp>
#include <nlohmann/json.hpp>
#include <cassert>
#include <fstream>
#include <iostream>
using namespace hb::gpu;using Json=nlohmann::json;
static std::vector<std::uint8_t> decode(const std::string& text){const std::string chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";std::vector<std::uint8_t> out;unsigned value=0,bits=0;for(char c:text){if(c=='=')break;const auto at=chars.find(c);if(at==std::string::npos)throw std::runtime_error("base64");value=(value<<6)|static_cast<unsigned>(at);bits+=6;if(bits>=8){bits-=8;out.push_back(static_cast<std::uint8_t>(value>>bits));}}return out;}
int main(int argc,char**argv){assert(argc==2);std::ifstream file(argv[1]);Json cases;file>>cases;Device gpu;SceneRenderer renderer(gpu,16,16);auto mesh=renderer.createMesh({{{-1,-1,.4f}},{{1,-1,.4f}},{{1,1,.4f}},{{-1,1,.4f}}},{0,1,2,0,2,3});SceneMaterial material;material.unlit=true;material.toneMapped=false;material.doubleSided=true;SceneFrame frame;frame.ambient={0,0,0,1};Json rows=Json::array();
for(const auto& test:cases){const auto& p=test.at("packet");const auto kind=test.at("kind").get<std::string>();const bool volume=kind=="texture3d",cube=kind=="texturecube",flat=kind=="texture2d";std::vector<SceneRenderer::TextureMipLevel> levels;for(const auto& l:p.value("mipLevels",Json::array()))levels.push_back({l.at("width"),l.at("height"),decode(l.at("rgbaBase64")),l.value("layers",1u)});auto texture=renderer.createDataTexture(p.at("width"),p.at("height"),decode(p.at("rgbaBase64")),4,false,p.at("layers"),false,!volume&&!cube&&!flat,cube?"cube":volume?"volume":"2d",false,false,levels);const std::uint64_t expectedBytes=test.at("info").at("residentBytes");assert(texture.storageBytes()==expectedBytes);
const std::string coordinate=flat?"float2(hbParameters[0],hbParameters[1])":"float3(hbParameters[0],hbParameters[1],hbParameters[2])";auto program=renderer.createProgram(std::string(flat?"Texture2D":cube?"TextureCube":volume?"Texture3D":"Texture2DArray")+" tex:register(t8);SamplerState samp:register(s0);StructuredBuffer<float> hbParameters:register(t7);","base=tex.SampleLevel(samp,"+coordinate+",hbParameters[3]);",{0,0,0,0});Json samples=Json::array();int maxError=0;
for(const auto& s:test.at("samples")){const auto c=s.at("coordinate").get<std::vector<float>>();renderer.setProgramParameters(program,{c[0],c[1],c[2],s.at("physicalLOD").get<float>()});renderer.begin(frame);renderer.draw(mesh,identity,identity,material,{}, {},0,0,&program,{&texture},{0});const auto pixels=renderer.readPixels();std::array<int,4> rgba{};for(int ch=0;ch<4;ch++){rgba[ch]=pixels[(8*16+8)*4+ch];const double linear=s.at("expected")[ch];const int expected=static_cast<int>(std::lround(255.0*(ch==3?linear:linear<=.0031308?linear*12.92:1.055*std::pow(linear,1.0/2.4)-.055)));const int error=std::abs(rgba[ch]-expected);assert(error<3);maxError=std::max(maxError,error);}samples.push_back({{"logical",s.at("logical")},{"physicalLOD",s.at("physicalLOD")},{"rgba",rgba}});}
rows.push_back({{"kind",kind},{"base",test.at("base")},{"storageBytes",texture.storageBytes()},{"samples",samples},{"displayByteMaxError",maxError}});
}std::cout<<Json{{"passed",true},{"actualD3D11",true},{"rows",rows}};}
